class Solution:
    def bestRotation(self, nums: List[int]) -> int:
        n = len(nums)
        best_k, best_score = 0, -1
        for k in range(n):
            score = 0
            for i in range(n):
                if nums[i] <= (i - k + n) % n:
                    score += 1
            if score > best_score:
                best_score, best_k = score, k
        return best_k

