class Solution {
public:
    int bestRotation(vector<int>& nums) {
        int n = nums.size();
        int bestK = 0, bestScore = -1;
        for (int k = 0; k < n; ++k) {
            int score = 0;
            for (int i = 0; i < n; ++i)
                if (nums[i] <= (i - k + n) % n) ++score;
            if (score > bestScore) { bestScore = score; bestK = k; }
        }
        return bestK;
    }
};

