class Solution:
    def bestRotation(self, nums: List[int]) -> int:
        n = len(nums)
        diff = [0] * (n + 1)
        for i, v in enumerate(nums):
            lo = (i - v + 1 + n) % n
            hi = (i + 1) % n
            diff[lo] += 1
            diff[hi] -= 1
        best_k, best_bad, cur = 0, n + 1, 0
        for k in range(n):
            cur += diff[k]
            if cur < best_bad:
                best_bad, best_k = cur, k
        return best_k

