public:
    int bestRotation(vector<int>& nums) {
        int n = nums.size();
        vector<int> diff(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            int lo = (i - nums[i] + 1 + n) % n;
            int hi = (i + 1) % n;
            ++diff[lo];
            --diff[hi];
        }
        int bestK = 0, bestBad = n + 1, cur = 0;
        for (int k = 0; k < n; ++k) {
            cur += diff[k];
            if (cur < bestBad) { bestBad = cur; bestK = k; }
        }
        return bestK;
    }
};

